-- Dữ liệu quỹ thu chi import từ Excel (2 tháng 7-8/2026)
BEGIN;
-- Guard: chỉ import khi chưa có dữ liệu (chạy lại lần 2 sẽ tự bỏ qua, không nhân đôi)
DO $$ BEGIN
  IF (SELECT COUNT(*) FROM fund_transactions) > 0 THEN
    RAISE EXCEPTION 'Fund data already imported - skipping (this is safe)';
  END IF;
END $$;
COMMIT;
